package paasio

import (
	"io"
	"sync"
)

// readCounter wraps an io.Reader and counts the number of bytes read and
// the number of Read calls made.
type readCounter struct {
	r     io.Reader
	mu    sync.Mutex
	bytes int64
	ops   int
}

// writeCounter wraps an io.Writer and counts the number of bytes written and
// the number of Write calls made.
type writeCounter struct {
	w     io.Writer
	mu    sync.Mutex
	bytes int64
	ops   int
}

// readWriteCounter wraps an io.ReadWriter and counts both reads and writes.
type readWriteCounter struct {
	readCounter
	writeCounter
}

func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{w: writer}
}

func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{r: reader}
}

func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  readCounter{r: readwriter},
		writeCounter: writeCounter{w: readwriter},
	}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.r.Read(p)
	rc.mu.Lock()
	if err == nil {
		rc.bytes += int64(n)
	}
	rc.ops++
	rc.mu.Unlock()
	return n, err
}

func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.bytes, rc.ops
}

func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.w.Write(p)
	wc.mu.Lock()
	if err == nil {
		wc.bytes += int64(n)
	}
	wc.ops++
	wc.mu.Unlock()
	return n, err
}

func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.bytes, wc.ops
}
